mapper.select:
SELECT
    dpp.prod_plan_id,
    dpp.prod_id,
    TO_CHAR(dpp.OPEN_START_DATE,'yyyy-mm-dd') openStartDateStr,
    TO_CHAR(dpp.OPEN_END_DATE,'yyyy-mm-dd') openEndDateStr,
    TO_CHAR(dpp.COLLINGOFF_PERIOD,'yyyy-mm-dd') collingoffPeriodStr,
    TO_CHAR(dpp.OPERATION_START_DATE,'yyyy-mm-dd') operationStartDateStr,
    TO_CHAR(dpp.AUTO_REDEEM_DATE,'yyyy-mm-dd') autoRedeemDateStr,
    dpp.HOLD_DAYS holdDays ,
    TO_CHAR(dpp.HOLD_DAYS) holdDaysStr  ,
    dpp.DATA_STATUS dataStatus,
    dpp.DATA_SOURCE dataSource,
    dpp.UPDATE_USER updateUser,
    TO_CHAR(NVL(dpp.Update_Time,dpp.Create_Time),'yyyy-mm-dd hh24:mi:ss') updateDateStr,
    rpi.prod_name prodName
FROM DIS_PROD_PLAN dpp
LEFT JOIN REP_PROD_INFO rpi ON rpi.PROD_ID = dpp.PROD_ID WHERE 1=1

    AND dpp.DATA_STATUS IN

        #{item}



    AND dpp.PROD_ID IN

        #{item}



    AND to_char(dpp.OPEN_START_DATE,'yyyy-mm-dd') >= #{openStartDateBegin,jdbcType=VARCHAR}


    AND to_char(dpp.OPEN_START_DATE,'yyyy-mm-dd') <= #{openStartDateEnd,jdbcType=VARCHAR}



    AND to_char(dpp.OPEN_END_DATE,'yyyy-mm-dd') >= #{openEndDateBegin,jdbcType=VARCHAR}


    AND to_char(dpp.OPEN_END_DATE,'yyyy-mm-dd') <= #{openEndDateEnd,jdbcType=VARCHAR}



    AND to_char(dpp.OPERATION_START_DATE,'yyyy-mm-dd') >= #{operationStartDateBegin,jdbcType=VARCHAR}


    AND to_char(dpp.OPERATION_START_DATE,'yyyy-mm-dd') <= #{operationStartDateEnd,jdbcType=VARCHAR}


    AND to_char(dpp.AUTO_REDEEM_DATE,'yyyy-mm-dd') >= #{autoRedeemDateBegin,jdbcType=VARCHAR}


    AND to_char(dpp.AUTO_REDEEM_DATE,'yyyy-mm-dd') <= #{autoRedeemDateEnd,jdbcType=VARCHAR}

order by NVL(dpp.UPDATE_TIME,dpp.CREATE_TIME) desc

select PROD_PLAN_ID, PROD_ID, OPEN_START_DATE, OPEN_END_DATE, COLLINGOFF_PERIOD, OPERATION_START_DATE, AUTO_REDEEM_DATE, HOLD_DAYS, DATA_STATUS, DATA_SOURCE, CREATE_USER, CREATE_TIME, UPDATE_USER, UPDATE_TIME, CREATE_DEPT from DIS_PROD_PLAN where PROD_ID = #{prodId,jdbcType=VARCHAR}
AND DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}
and rownum <= 1
